const norm = (s: string) =>
  s
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[\u05B0-\u05C7]/g, "")
    .toLowerCase()
    .replace(/["'\u05F3\u05F4\u2018\u2019\u201C\u201D\u05BE.]/g, "")
    .replace(/[^\p{L}\p{N}]+/gu, " ")
    .trim();

let INDEX: Map<string, string> | null = null;
function index(): Map<string, string> {
  if (INDEX) return INDEX;
  const m = new Map<string, string>();
  for (const [cc, n] of Object.entries(COUNTRY_NAMES)) for (const v of [n.he, n.en, n.es]) m.set(norm(v), cc);
  for (const [cc, list] of Object.entries(COUNTRY_ALIASES)) for (const v of list) m.set(norm(v), cc);
  INDEX = m;
  return m;
}

// Resolves a free-text country string ("USA", "ארצות הברית", "Hafar Al Batin Saudi Arabia",
// "דובאי - איחוד האמירויות הערביות") to an ISO2 code, or null when it cannot be done safely.
export function resolveCountry(text: string | null | undefined): string | null {
  if (!text) return null;
  const idx = index();
  const whole = idx.get(norm(text)) || idx.get(norm(text).replace(/d+/g, " ").replace(/s+/g, " ").trim());
  if (whole) return whole;
  // Segments split on comma / dash, last segment first (the country is last in "City, Country").
  const segs = text.split(/[,\u2013\u2014-]+/).map((s) => s.trim()).filter(Boolean).reverse();
  for (const s of segs) { const hit = idx.get(norm(s)); if (hit) return hit; }
  // Trailing words: "Hafar Al Batin Saudi Arabia" -> "saudi arabia" (up to 4 words).
  const words = norm(text).split(" ");
  for (let n = Math.min(4, words.length); n >= 1; n--) {
    const hit = idx.get(words.slice(-n).join(" "));
    if (hit) return hit;
  }
  return null;
}

